{
  "code": "export default async function ({ page }) {
  const EMAIL = 'jessicamendesbarbosa5@gmail.com';
  const SENHA = 'amovoced28';
  const w = (ms) => new Promise(r => setTimeout(r, ms));
  let d = [];

  try {
    // STEALTH
    await page.evaluateOnNewDocument(() => {
      Object.defineProperty(navigator, 'webdriver', { get: () => false });
      Object.defineProperty(navigator, 'plugins', { get: () => [1, 2, 3, 4, 5] });
      Object.defineProperty(navigator, 'languages', { get: () => ['pt-BR', 'pt', 'en-US', 'en'] });
      window.chrome = { runtime: {} };
    });
    await page.setUserAgent('Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36');
    await page.setViewport({ width: 1280, height: 800 });

    await page.goto('https://app.cotadorsimplificado.com.br/login', { waitUntil: 'networkidle2', timeout: 30000 });
    d.push('page');
    await w(1500);

    // EMAIL
    const eInp = await page.$('#email_principal');
    if (eInp) {
      await eInp.click();
      await w(300);
      await eInp.type(EMAIL, { delay: 50 });
    }
    await w(800);
    d.push('email');

    // CONTINUAR
    await page.evaluate(() => {
      const b = [...document.querySelectorAll('button')].find(x => x.textContent.includes('Continuar com Email'));
      if(b) b.click();
    });
    await w(3000);
    d.push('cont');

    // SENHA
    let pwdFound = false;
    for (let i = 0; i < 5; i++) {
      const pwd = await page.$('#pwdInput');
      if (pwd) {
        pwdFound = true;
        await pwd.click();
        await w(300);
        await pwd.type(SENHA, { delay: 50 });
        d.push('senha');
        break;
      }
      await w(1000);
    }
    if (!pwdFound) {
      return { success: false, error: 'pwdInput not found', debug: d };
    }
    await w(800);

    // ENTRAR - usando click direto no elemento
    const entrarResult = await page.evaluate(() => {
      const buttons = document.querySelectorAll('button');
      for (const b of buttons) {
        if (b.textContent.trim() === 'Entrar') {
          b.click();
          return 'clicked';
        }
      }
      return 'not found';
    });
    d.push('entrar:' + entrarResult);

    // ESPERA MAIS TEMPO para o login processar
    d.push('waiting...');
    await w(6000);

    // DEBUG: verifica estado da pagina
    const urlAfter = page.url();
    d.push('url1:' + urlAfter.substring(0, 50));

    const pageState = await page.evaluate(() => {
      const body = document.body;
      if (!body) return { error: 'no body' };

      const text = body.innerText.substring(0, 500);
      const hasError = text.includes('Senha incorreta') || text.includes('erro') || text.includes('inválid');
      const hasHapvida = !!document.querySelector('img[src*="hapvida"]');
      const hasOperadoras = text.includes('Operadoras') || text.includes('Cotador');
      const buttons = [...document.querySelectorAll('button')].map(b => b.textContent.trim().substring(0, 20)).join(', ');

      return { hasError, hasHapvida, hasOperadoras, buttons: buttons.substring(0, 100), text: text.substring(0, 200) };
    });

    d.push('err:' + pageState.hasError);
    d.push('hap:' + pageState.hasHapvida);
    d.push('oper:' + pageState.hasOperadoras);

    // Se ainda na pagina de login, espera mais
    if (urlAfter.includes('/login')) {
      d.push('still login, waiting more...');
      await w(5000);
      const urlAfter2 = page.url();
      d.push('url2:' + urlAfter2.substring(0, 50));
    }

    // Tenta clicar no Hapvida se existir
    if (pageState.hasHapvida) {
      await page.evaluate(() => {
        const img = document.querySelector('img[src*="hapvida"]');
        if(img) {
          const p = img.closest('.clickable-element') || img.parentElement.parentElement;
          if(p) p.click();
        }
      });
      d.push('hapvida clicked');
      await w(2000);
    }

    const finalUrl = page.url();
    const cookies = await page.cookies();

    return {
      success: true,
      debug: d,
      url: finalUrl,
      cookieCount: cookies.length,
      pageState
    };
  } catch (error) {
    d.push('ERR:' + error.message.substring(0, 50));
    return { success: false, error: error.message, debug: d };
  }
}"
}
